module crc16_stream_core (
    input wire clk,
    input wire rst,
    input wire [7:0] in_data,
    input wire in_last,
    input wire in_valid,
    output wire in_ready,
    output wire [15:0] out_crc,
    output wire out_last,
    output wire out_valid,
    input wire out_ready
);

    reg [15:0] frame_crc;
    reg [15:0] out_crc_reg;
    reg out_last_reg;
    reg out_valid_reg;

    assign in_ready = !out_valid_reg || out_ready;
    assign out_crc = out_crc_reg;
    assign out_last = out_last_reg;
    assign out_valid = out_valid_reg;

    function [15:0] crc16_update;
        input [15:0] crc_in;
        input [7:0] data_in;
        reg [15:0] crc;
        integer i;
        begin
            crc = crc_in ^ {data_in, 8'h00};
            for (i = 0; i < 8; i = i + 1) begin
                if (crc[15])
                    crc = (crc << 1) ^ 16'h1021;
                else
                    crc = crc << 1;
            end
            crc16_update = crc;
        end
    endfunction

    wire [15:0] next_crc;
    assign next_crc = crc16_update(frame_crc, in_data);

    always @(posedge clk) begin
        if (rst) begin
            frame_crc <= 16'hFFFF;
            out_crc_reg <= 16'h0000;
            out_last_reg <= 1'b0;
            out_valid_reg <= 1'b0;
        end else if (in_ready) begin
            if (in_valid) begin
                out_crc_reg <= next_crc;
                out_last_reg <= in_last;
                out_valid_reg <= 1'b1;
                if (in_last)
                    frame_crc <= 16'hFFFF;
                else
                    frame_crc <= next_crc;
            end else if (out_valid_reg && out_ready) begin
                out_valid_reg <= 1'b0;
            end
        end
    end

endmodule
